def aplicar_confirmacao_b(bancos):
    for item in bancos:
        key=item['id']
        if key not in ERROS:continue
        cards=item['cards']
        cards[17]['f']=FECHOS[key]
        for i,(question,value) in VF[key].items():cards[i].update(p=question,v=value)
        if key=='m2-f14':
            cards[6]['f']='«Vilão → vilãozinho» forma uma palavra derivada; «vilão → vilões» produz o plural. O ancinho no retrato imaginado já pertence à construção do retrato e ao seu efeito.'
            cards[18]['f']='Dizer que Inês associa o universo rural à falta de distinção atribui-lhe a avaliação. Falar de inferioridade confirmada pela narração ou de pequena dimensão converte o olhar da personagem numa regra geral ou numa desvalorização assumida pela análise.'
        if key=='m2-f15':
            import re
            cards[7]['html']=re.sub(r'<p><strong>Modelo completo.</strong>.*?</p>','<p><strong>Modelo completo.</strong> O par «autocarro» e «ônibus» está documentado como diferença lexical entre variedades. A origem dos exemplos sustenta a classificação. A fala do Ermitão pede outra pergunta: não é uma variedade do português, é castelhano.</p>',cards[7]['html'])
        if key=='m2-f16':
            cards[18]['f']='Perguntar como a resposta altera o peso do relato observa uma relação textual. Perguntar pela intenção do clérigo ou pela invenção do incidente pressupõe conclusões que não foram demonstradas e apaga a distinção entre relato e reação.'
        if key=='m5-f17':
            cards[15]['f']='Contar a interceção antes da espera reorganiza os mesmos factos. A recusa de Simão e a desistência da mãe mudam os acontecimentos e não servem para isolar o efeito da ordem narrativa.'
        false_claims={
          'm1-f21':{1:'Antes de reler. Na cantiga de amor, o sofrimento da voz correspondia a um episódio comprovado da vida do trovador?'},
          'm3-f19':{1:'Antes de reler. Na lírica camoniana, nomear uma imagem equivale a explicar o seu efeito no conjunto do poema?'},
          'm5-f16':{5:'A prioridade dada ao conhecimento concreto corresponde a uma recusa da leitura como aprendizagem.'},
          'm5-f17':{1:'Antes de reler. Nas cartas do romance, aquilo que se escreve coincide com o que o destinatário chega a conhecer?'},
          'm2-f16':{5:'A hipótese da Mãe é a explicação que a cena dá para o que aconteceu a Lianor.'}}
        for i,prompt in false_claims.get(key,{}).items():cards[i]['p']=prompt
        for i,wrong in ERROS[key].items():
            c=cards[i];assert c['t']=='escolha' and c['c']==0
            c['fe']=[c['f'],*wrong]
        # 02/11/2026: achado 3 da confirmação (a pergunta revista da M1-F21 deixou de ser aplicada depois da correção do #148).
        if key=='m1-f21':cards[18]['p']='Que comentário distingue o desejo da sua realização?'
        for i,reread in RELEITURAS_B[key].items():
            assert cards[i]['t'] not in ('ler','escolha') and 'fe' not in cards[i],(key,i)
            cards[i]['fe']=reread
        # 02/11/2026: achado 19, rótulos próprios das leituras, como nas lições publicadas.
        cards[3]['rot']='Lê de perto';cards[7]['rot']='Para entender';cards[13]['rot']='Compara'
        item['cards']=[cards[i] for i in ORDENS[key]]
